<script setup lang="ts">
import { reactive, ref } from 'vue'
import { Plus, CalendarDays, Laptop, Pencil, Trash2 } from 'lucide-vue-next'
import { useApi, refreshData } from '../composables/query'
import { api, patch, post } from '../services/api'
import { useSession } from '../stores/session'
import type { Lookup } from '../types'
import AsyncState from '../components/AsyncState.vue'
import ConfirmationDialog from '../components/ConfirmationDialog.vue'
import DataTable from '../components/DataTable.vue'
const session=useSession(), {data,loading,error,refresh}=useApi<{leave:Lookup[];mobile:Lookup[]}>('/policies')
const holidays=useApi<{id:number;date:string;name:string;calendar_id:number}[]>('/holidays'),calendars=useApi<Lookup[]>('/holiday-calendars'),schedules=useApi<Lookup[]>('/schedules'),types=useApi<Lookup[]>('/leave-types')
const modal=ref(''),kind=ref('leave'),editing=ref<number|null>(null),busy=ref(false),failure=ref(''),form=reactive<Record<string,any>>({}),countryList=ref('')
const leaveDefault={name:'',annual_allowance:25,carryover_limit:5,carryover_expiry_month:3,accrual_frequency:'ANNUAL',allow_hr_override:false,valid_from:'2020-01-01',valid_until:null}
const mobileDefault={name:'',monthly_limit:8,weekly_limit:3,allowed_weekdays:[0,1,2,3,4],advance_notice_days:0,restricted_countries:[],allowed_locations:['HOME','OTHER','ABROAD'],approval_required:true,international_requires_hr:true,allow_hr_override:false}
function open(type:string,record?:Lookup,policyKind='leave'){modal.value=type;kind.value=policyKind;editing.value=record?.id||null;failure.value='';Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,type==='policy'?(policyKind==='leave'?structuredClone(leaveDefault):structuredClone(mobileDefault)):type==='holiday'?{calendar_id:1,name:'',date:''}:type==='schedule'?{name:'',weekdays:[0,1,2,3,4],hours_per_day:8,holiday_calendar_id:1,work_on_holidays:false}:type==='calendar'?{name:''}:{name:'',paid:true,tracks_balance:true,allow_half_day:true,approval_required:true});if(record)Object.assign(form,record);delete form.id;countryList.value=(form.restricted_countries||[]).join(', ')}
async function save(){busy.value=true;failure.value='';try{if(modal.value==='policy'){if(kind.value==='mobile')form.restricted_countries=countryList.value.split(',').map(s=>s.trim().toUpperCase()).filter(Boolean);const body={kind:kind.value,config:form};await(editing.value?patch(`/policies/${editing.value}`,body):post('/policies',body))}else await post(modal.value==='holiday'?'/holidays':modal.value==='schedule'?'/schedules':modal.value==='calendar'?'/holiday-calendars':'/leave-types',form);modal.value='';await refreshData();session.message('Company configuration saved.')}catch(e){failure.value=(e as Error).message}finally{busy.value=false}}
const deleting=ref<number|null>(null)
async function remove(){busy.value=true;failure.value='';try{await api(`/holidays/${deleting.value}`,{method:'DELETE'});deleting.value=null;await refreshData()}catch(e){failure.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">CLEAR RULES, HAPPIER TEAMS</div><h1>Policies & holidays</h1><p>Flexible working, shaped around your organization.</p></div><button class="btn primary" @click="open('policy')"><Plus :size="17"/>New policy</button></div><AsyncState :loading="loading" :error="error" @retry="refresh"><div class="policy-columns"><section class="panel"><div class="section-heading"><h2><CalendarDays :size="19"/>Leave policies</h2></div><article v-for="policy in data?.leave" :key="policy.id" class="policy-card"><div class="flex-between"><h3>{{policy.name}}</h3><button class="icon-btn" :aria-label="`Edit ${policy.name}`" @click="open('policy',policy,'leave')"><Pencil :size="16"/></button></div><div class="policy-number">{{policy.annual_allowance}}<span> days per year</span></div><p>Carryover up to {{policy.carryover_limit}} days · {{String(policy.accrual_frequency).toLowerCase()}} accrual</p><span class="status approved">{{policy.allow_hr_override?'HR exceptions enabled':'Standard approval'}}</span></article></section><section class="panel"><div class="section-heading"><h2><Laptop :size="19"/>Mobile-work policies</h2><button class="text-link" @click="open('policy',undefined,'mobile')">Add</button></div><article v-for="policy in data?.mobile" :key="policy.id" class="policy-card"><div class="flex-between"><h3>{{policy.name}}</h3><button class="icon-btn" :aria-label="`Edit ${policy.name}`" @click="open('policy',policy,'mobile')"><Pencil :size="16"/></button></div><div class="policy-number">{{policy.monthly_limit}}<span> days per month</span></div><p>Up to {{policy.weekly_limit}} days per week · {{policy.advance_notice_days}} days’ notice</p><span class="status approved">{{policy.international_requires_hr?'International work reviewed by HR':'Manager review'}}</span></article></section></div></AsyncState><section class="panel"><div class="section-heading"><div><h2>Company holidays</h2><p class="muted">Maintain the calendar used by your working schedules.</p></div><button v-if="session.has('HR')" class="btn secondary" @click="open('holiday')"><Plus :size="16"/>Add holiday</button></div><AsyncState :loading="holidays.loading.value" :error="holidays.error.value" @retry="holidays.refresh"><DataTable :headers="['Holiday','Date','Calendar','']"><tr v-for="holiday in holidays.data.value" :key="holiday.id"><td><strong>{{holiday.name}}</strong></td><td>{{holiday.date}}</td><td>{{calendars.data.value?.find(c=>c.id===holiday.calendar_id)?.name}}</td><td><button v-if="session.has('HR')" class="icon-btn" :aria-label="`Delete ${holiday.name}`" @click="deleting=holiday.id;failure='' "><Trash2 :size="16"/></button></td></tr></DataTable></AsyncState></section><div v-if="session.has('HR')" class="policy-columns mt-6"><section class="panel"><div class="section-heading"><h2>Working schedules</h2><button class="text-link" @click="open('schedule')">Add schedule</button></div><div v-for="s in schedules.data.value" :key="s.id" class="policy-card"><h3>{{s.name}}</h3><p>{{s.hours_per_day}} hours per working day</p></div><button class="btn secondary ml-6 mb-6" @click="open('calendar')">Add holiday calendar</button></section><section class="panel"><div class="section-heading"><h2>Leave categories</h2><button class="text-link" @click="open('type')">Add category</button></div><div v-for="t in types.data.value" :key="t.id" class="policy-card"><h3>{{t.name}}</h3><p>{{t.paid?'Paid':'Unpaid'}} · {{t.tracks_balance?'Balance tracked':'No balance deduction'}}</p></div></section></div><ConfirmationDialog :open="!!modal" :title="modal==='policy'?(editing?'Edit policy':'Create policy'):`Add ${modal}`" @close="modal='' "><form @submit.prevent="save"><label>Name<input v-model="form.name" required maxlength="120"></label><template v-if="modal==='policy'"><label v-if="!editing">Policy type<select v-model="kind" @change="open('policy',undefined,kind)"><option value="leave">Annual leave</option><option value="mobile">Mobile work</option></select></label><template v-if="kind==='leave'"><div class="form-grid"><label>Annual allowance<input v-model.number="form.annual_allowance" type="number" min="0" max="366" step="0.5" required></label><label>Carryover limit<input v-model.number="form.carryover_limit" type="number" min="0" max="366" step="0.5" required></label><label>Carryover expiry month<select v-model="form.carryover_expiry_month"><option :value="null">No expiry</option><option v-for="month in 12" :value="month">{{month}}</option></select></label><label>Accrual frequency<select v-model="form.accrual_frequency"><option>ANNUAL</option><option>MONTHLY</option></select></label><label>Valid from<input v-model="form.valid_from" type="date" required></label><label>Valid until<input v-model="form.valid_until" type="date" @change="form.valid_until=form.valid_until||null"></label></div></template><template v-else><div class="form-grid"><label>Monthly limit<input v-model.number="form.monthly_limit" type="number" min="0" max="31" step="0.5" required></label><label>Weekly limit<input v-model.number="form.weekly_limit" type="number" min="0" max="7" step="0.5" required></label><label>Advance notice (days)<input v-model.number="form.advance_notice_days" type="number" min="0" max="365" required></label></div><fieldset><legend>Allowed weekdays</legend><div class="weekday-picker"><label v-for="(day,i) in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']" :key="day" class="checkbox-label"><input v-model="form.allowed_weekdays" type="checkbox" :value="i">{{day}}</label></div></fieldset><label>Restricted country codes<input v-model="countryList" placeholder="Comma-separated, e.g. XX, YY"></label><fieldset><legend>Permitted locations</legend><label v-for="location in ['HOME','OTHER','ABROAD']" class="checkbox-label"><input v-model="form.allowed_locations" type="checkbox" :value="location">{{location}}</label></fieldset><label class="checkbox-label"><input v-model="form.approval_required" type="checkbox">Manager approval required</label><label class="checkbox-label"><input v-model="form.international_requires_hr" type="checkbox">HR review for international work</label></template><label class="checkbox-label"><input v-model="form.allow_hr_override" type="checkbox">Allow documented HR policy overrides</label></template><template v-if="modal==='holiday'"><label>Date<input v-model="form.date" type="date" required></label><label>Calendar<select v-model.number="form.calendar_id"><option v-for="c in calendars.data.value" :value="c.id">{{c.name}}</option></select></label></template><template v-if="modal==='schedule'"><label>Holiday calendar<select v-model.number="form.holiday_calendar_id"><option v-for="c in calendars.data.value" :value="c.id">{{c.name}}</option></select></label><label>Hours per day<input v-model.number="form.hours_per_day" type="number" min="1" max="24" step="0.5"></label><fieldset><legend>Working weekdays</legend><div class="weekday-picker"><label v-for="(day,i) in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']" :key="day" class="checkbox-label"><input v-model="form.weekdays" type="checkbox" :value="i">{{day}}</label></div></fieldset><label class="checkbox-label"><input v-model="form.work_on_holidays" type="checkbox">Schedule includes public holidays</label></template><template v-if="modal==='type'"><label v-for="[key,label] in [['paid','Paid leave'],['tracks_balance','Track leave balance'],['allow_half_day','Allow half days'],['approval_required','Require approval']]" class="checkbox-label"><input v-model="form[key!]" type="checkbox">{{label}}</label></template><p v-if="failure" class="error-box" role="alert">{{failure}}</p><div class="form-actions"><button class="btn primary" :disabled="busy">{{busy?'Saving…':'Save changes'}}</button></div></form></ConfirmationDialog><ConfirmationDialog :open="deleting!==null" title="Remove holiday?" description="Pending requests will use the updated calendar when approved. Approved accounting snapshots remain unchanged." @close="deleting=null"><p v-if="failure" class="error-box">{{failure}}</p><button class="btn danger" :disabled="busy" @click="remove">Remove holiday</button></ConfirmationDialog></template>
